// порядок не важен: O(1) на удаление, без сдвигов
for (int i = enemies.Count - 1; i >= 0; i--) {
    if (!enemies[i].IsDead) continue;
    int last = enemies.Count - 1;
    enemies[i] = enemies[last];   // последний — на место мёртвого
    enemies.RemoveAt(last);       // удаление с конца ничего не сдвигает
}
